void MimeHeaders_free(MimeHeaders* hdrs) {
  if (!hdrs) return;
  PR_FREEIF(hdrs->all_headers);
  PR_FREEIF(hdrs->heads);
  PR_FREEIF(hdrs->munged_subject);

  PR_Free(hdrs);
